import{_ as t,c as a,a2 as e,o}from"./chunks/framework.Bzjhwp8w.js";const s="/dllm/assets/af64be5ddf1a3ffc104d76873604db76.mK4p2YB1.png",h=JSON.parse('{"title":"向量存储 RAG","description":"向量存储 RAG","frontmatter":{"title":"向量存储 RAG","description":"向量存储 RAG","layout":"doc"},"headers":[],"relativePath":"langflow/starter-projects-vector-store-rag.md","filePath":"langflow/starter-projects-vector-store-rag.md"}'),l={name:"langflow/starter-projects-vector-store-rag.md"};function n(i,r,g,c,p,d){return o(),a("div",null,r[0]||(r[0]=[e('<h1 id="向量存储-rag" tabindex="-1">向量存储 RAG <a class="header-anchor" href="#向量存储-rag" aria-label="Permalink to &quot;向量存储 RAG&quot;">​</a></h1><p>检索增强生成（Retrieval Augmented Generation，简称 RAG）是一种在您的数据上训练大型语言模型（LLMs）并进行查询的模式。</p><p>RAG 依托于<strong>向量存储</strong>，即一种存储已摄取数据的嵌入的向量数据库。</p><p>这使得<strong>向量搜索</strong>成为可能，一种更强大且具有上下文感知的搜索方式。</p><p>我们选择了 <a href="https://astra.datastax.com/signup?utm_source=langflow-pre-release&amp;utm_medium=referral&amp;utm_campaign=langflow-announcement&amp;utm_content=create-a-free-astra-db-account" target="_blank" rel="noreferrer">Astra DB</a> 作为此入门流程的向量数据库，但您也可以使用 Langflow 的任何其他向量数据库选项进行操作。</p><h2 id="先决条件" tabindex="-1">先决条件 <a class="header-anchor" href="#先决条件" aria-label="Permalink to &quot;先决条件&quot;">​</a></h2><ul><li><a href="https://platform.openai.com/" target="_blank" rel="noreferrer">OpenAI API 密钥</a></li><li>一个 <a href="https://docs.datastax.com/en/astra-db-serverless/get-started/quickstart.html" target="_blank" rel="noreferrer">Astra DB 向量数据库</a> ，需要： <ul><li>一个 Astra DB 应用程序令牌</li><li><a href="https://docs.datastax.com/en/astra-db-serverless/databases/manage-collections.html#create-collection" target="_blank" rel="noreferrer">Astra 中的一个集合</a></li></ul></li></ul><h2 id="打开-langflow-并开始一个新项目" tabindex="-1">打开 Langflow 并开始一个新项目 <a class="header-anchor" href="#打开-langflow-并开始一个新项目" aria-label="Permalink to &quot;打开 Langflow 并开始一个新项目&quot;">​</a></h2><ol><li>在 Langflow 仪表板上，点击 <strong>New Flow</strong>（新流程）。</li><li>选择 <strong>Vector Store RAG</strong>（向量存储 RAG）。</li><li><strong>Vector Store RAG</strong> 流程已创建。</li></ol><h2 id="构建向量rag流程" tabindex="-1">构建向量RAG流程 <a class="header-anchor" href="#构建向量rag流程" aria-label="Permalink to &quot;构建向量RAG流程&quot;">​</a></h2><p>向量存储RAG流程由用于数据摄入（ingestion）和查询的两个独立流程构成。</p><p><img src="'+s+'" alt=""></p><p>屏幕底部的**加载数据流程**会创建一个可搜索的索引，用于查询上下文相似性。此流程会将本地文件中的数据填入向量存储。它从本地文件中获取数据，将其分割成多个块，将其索引在 Astra DB 中，并使用 OpenAI 嵌入（embeddings）模型计算这些块的嵌入向量。</p><p>屏幕顶部的**检索流程**会将用户的查询嵌入到向量中，这些向量将与**加载数据流程**中向量存储的数据进行比较，以判断上下文相似性。</p><ul><li><strong>Chat 输入</strong>接收来自<strong>Playground</strong>的用户输入。</li><li><strong>OpenAI 嵌入</strong>将用户查询转换为向量形式。</li><li><strong>Astra DB</strong>使用查询向量进行相似度搜索。</li><li><strong>数据解析</strong>处理检索到的数据块。</li><li><strong>提示构建</strong>将用户查询与相关上下文结合。</li><li><strong>OpenAI</strong>使用提示生成响应。</li><li><strong>Chat 输出</strong>将响应返回给<strong>Playground</strong>。</li></ul><ol><li><p>配置<strong>OpenAI</strong>模型组件。</p><ol><li>要为<strong>OpenAI</strong>组件创建一个全局变量，在<strong>OpenAI API Key</strong>字段中，点击<strong>Globe</strong>按钮，然后点击<strong>Add New Variable</strong>。</li><li>在<strong>Variable Name</strong>字段中，输入<code>openai_api_key</code>。</li><li>在<strong>Value</strong>字段中，粘贴你的 OpenAI API Key (<code>sk-...</code>)。</li><li>点击<strong>Save Variable</strong>。</li></ol></li><li><p>配置<strong>Astra DB</strong>组件。</p><ol><li>在<strong>Astra DB Application Token</strong>字段中，添加你的<strong>Astra DB</strong>应用程序令牌。该组件将连接到你的数据库，并填充菜单中现有的数据库和集合。</li><li>选择你的<strong>Database</strong>。</li><li>选择你的<strong>Collection</strong>。集合是在你的 <a href="https://astra.datastax.com" target="_blank" rel="noreferrer">Astra DB 部署</a>中创建的，用于存储向量数据。如果你没有集合，请参阅 <a href="https://docs.datastax.com/en/astra-db-serverless/databases/manage-collections.html#create-collection" target="_blank" rel="noreferrer">DataStax Astra DB Serverless 文档</a>。</li><li>选择<strong>嵌入模型</strong>以引入你自己的嵌入模型，这是连接的<strong>OpenAI 嵌入</strong>组件。<strong>Dimensions</strong>值必须与你的集合的维度匹配。你可以在 <a href="https://astra.datastax.com" target="_blank" rel="noreferrer">Astra DB 部署</a>中的<strong>Collection</strong>找到该值。</li></ol></li></ol><p>如果你使用了 Langflow 的<strong>Global Variables</strong>功能，RAG 应用流组件已经配置了必要的凭据。</p><h2 id="运行向量存储-rag-流程" tabindex="-1">运行向量存储 RAG 流程 <a class="header-anchor" href="#运行向量存储-rag-流程" aria-label="Permalink to &quot;运行向量存储 RAG 流程&quot;">​</a></h2><ol><li>点击 <strong>Playground</strong> 按钮。在这里，你可以和使用你创建的数据库上下文的AI进行对话。</li><li>输入一条消息并按下回车键。（试试输入类似“你了解哪些主题？”的问题）</li><li>机器人将会用总结你嵌入的数据的方式进行回应。</li></ol>',19)]))}const m=t(l,[["render",n]]);export{h as __pageData,m as default};
